True def transform(grid):
    """Composite four vertically stacked color layers by priority 5, 4, 8, 2."""
    h = len(grid)
    if h % 4 != 0:
        raise ValueError("expected four equal-height layers")
    layer_h = h // 4
    width = len(grid[0])
    out = [[0 for _ in range(width)] for _ in range(layer_h)]
    # The 5 layer is the base; at empty cells, 4 takes precedence over 8, then 2.
    for layer in (0, 1, 3, 2):
        for r in range(layer_h):
            for c in range(width):
                value = grid[layer * layer_h + r][c]
                if out[r][c] == 0 and value != 0:
                    out[r][c] = value
    return out
